import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:nusantara_cerdas_nav_707012400028/main.dart';
void main() { testWidgets('Alur utama dan perubahan state', (tester) async { await tester.pumpWidget(const NusantaraApp()); await tester.pumpAndSettle(); await tester.tap(find.text('Jelajahi Layanan')); await tester.pumpAndSettle(); await tester.tap(find.byTooltip('Favoritkan Izin Usaha Mikro')); await tester.pumpAndSettle(); await tester.tap(find.text('Izin Usaha Mikro')); await tester.pumpAndSettle(); await tester.tap(find.text('Ajukan Permohonan')); await tester.pump(const Duration(milliseconds:100)); expect(find.text('Sedang mengirim…'), findsOneWidget); await tester.pump(const Duration(seconds:3)); await tester.pumpAndSettle(); await tester.tap(find.text('Warga')); await tester.pumpAndSettle(); expect(find.text('Izin Usaha Mikro'), findsNWidgets(2)); await tester.tap(find.byType(Switch)); await tester.pumpAndSettle(); expect(tester.widget<MaterialApp>(find.byType(MaterialApp)).themeMode,ThemeMode.dark); expect(tester.takeException(),isNull); }); }
